function allocCurrencyWallets(cfg,base,mep){return{ARS:allocToBase(cfg.ars,'ARS',base,mep)||0,USD:allocToBase(cfg.usd,'USD',base,mep)||0,USDT:allocToBase(cfg.usdt,'USDT',base,mep)||0}}
function allocBuildProfile(def,cands,cfg,baseInfo,ctx){const newTotal=baseInfo.total,totalAfter=ctx.total+newTotal,minCashAmt=0,maxInvest=newTotal,alloc={items:new Map(),byEconomic:new Map(),bySector:new Map(),byFamily:new Map(),crypto:0,argentina:0,equity:0,highRisk:0,used:0},wallet=allocCurrencyWallets(cfg,baseInfo.base,baseInfo.mep),chunk=Math.max(newTotal*.025,newTotal/80),profileCrypto=Math.min(cfg.maxCrypto/100,def.maxCrypto),argCap=cfg.searchUniverse==='fixed'?1:cfg.maxArgentina/100;let guard=0;while(alloc.used+chunk<=maxInvest+1e-9&&guard++<500){let best=null,bestU=-Infinity,bestAmt=0;for(const c of cands){const selected=alloc.items.get(c.economicKey);if(selected&&selected.candidate!==c)continue;let cap=def.perAssetCap*totalAfter-(ctx.byEconomic.get(c.economicKey)||0)-(alloc.byEconomic.get(c.economicKey)||0);if(cap<=0)continue;const famNow=(ctx.byFamily.get(c.family)||0)+(alloc.byFamily.get(c.family)||0);if(c.family==='crypto'){cap=Math.min(cap,profileCrypto*totalAfter-ctx.crypto-alloc.crypto)}if(c.family==='equity'){const eqCap=cfg.searchUniverse==='variable'?1:def.maxEquity;cap=Math.min(cap,eqCap*totalAfter-ctx.equity-alloc.equity)}if(c.region==='Argentina'){cap=Math.min(cap,argCap*totalAfter-ctx.argentina-alloc.argentina)}if(c.risk>=4){cap=Math.min(cap,def.maxHighRisk*totalAfter-ctx.highRisk-alloc.highRisk)}if(cap<=0)continue;let available=maxInvest-alloc.used,amt=Math.min(chunk,cap,available);if(!cfg.allowFx){amt=Math.min(amt,wallet[c.currency]||0)}if(amt<=newTotal*.004)continue;const u=allocCandidateUtility(c,def,cfg,ctx,alloc,totalAfter);if(u>bestU){bestU=u;best=c;bestAmt=amt}}if(!best)break;const prev=alloc.items.get(best.economicKey)||{candidate:best,amount:0,utilitySum:0,chunks:0};prev.amount+=bestAmt;prev.utilitySum+=bestU;prev.chunks++;alloc.items.set(best.economicKey,prev);alloc.used+=bestAmt;alloc.byEconomic.set(best.economicKey,(alloc.byEconomic.get(best.economicKey)||0)+bestAmt);alloc.bySector.set(best.sector,(alloc.bySector.get(best.sector)||0)+bestAmt);alloc.byFamily.set(best.family,(alloc.byFamily.get(best.family)||0)+bestAmt);if(best.family==='crypto')alloc.crypto+=bestAmt;if(best.family==='equity')alloc.equity+=bestAmt;if(best.region==='Argentina')alloc.argentina+=bestAmt;if(best.risk>=4)alloc.highRisk+=bestAmt;if(!cfg.allowFx)wallet[best.currency]=Math.max(0,(wallet[best.currency]||0)-bestAmt)}let sweepGuard=0;while(maxInvest-alloc.used>newTotal*.00001&&sweepGuard++<100){let best=null,bestU=-Infinity,bestAmt=0;const remaining=maxInvest-alloc.used;for(const c of cands){const selected=alloc.items.get(c.economicKey);if(selected&&selected.candidate!==c)continue;let cap=def.perAssetCap*totalAfter-(ctx.byEconomic.get(c.economicKey)||0)-(alloc.byEconomic.get(c.economicKey)||0);if(cap<=0)continue;if(c.family==='crypto')cap=Math.min(cap,profileCrypto*totalAfter-ctx.crypto-alloc.crypto);if(c.family==='equity'){const eqCap=cfg.searchUniverse==='variable'?1:def.maxEquity;cap=Math.min(cap,eqCap*totalAfter-ctx.equity-alloc.equity)}if(c.region==='Argentina')cap=Math.min(cap,argCap*totalAfter-ctx.argentina-alloc.argentina);if(c.risk>=4)cap=Math.min(cap,def.maxHighRisk*totalAfter-ctx.highRisk-alloc.highRisk);let amt=Math.min(remaining,cap);if(!cfg.allowFx)amt=Math.min(amt,wallet[c.currency]||0);if(amt<=newTotal*.00001)continue;const u=allocCandidateUtility(c,def,cfg,ctx,alloc,totalAfter);if(u>bestU){bestU=u;best=c;bestAmt=amt}}if(!best)break;const prev=alloc.items.get(best.economicKey)||{candidate:best,amount:0,utilitySum:0,chunks:0};prev.amount+=bestAmt;prev.utilitySum+=bestU;prev.chunks++;alloc.items.set(best.economicKey,prev);alloc.used+=bestAmt;alloc.byEconomic.set(best.economicKey,(alloc.byEconomic.get(best.economicKey)||0)+bestAmt);alloc.bySector.set(best.sector,(alloc.bySector.get(best.sector)||0)+bestAmt);alloc.byFamily.set(best.family,(alloc.byFamily.get(best.family)||0)+bestAmt);if(best.family==='crypto')alloc.crypto+=bestAmt;if(best.family==='equity')alloc.equity+=bestAmt;if(best.region==='Argentina')alloc.argentina+=bestAmt;if(best.risk>=4)alloc.highRisk+=bestAmt;if(!cfg.allowFx)wallet[best.currency]=Math.max(0,(wallet[best.currency]||0)-bestAmt)}const rows=[...alloc.items.values()].map(x=>({...x.candidate,amountBase:x.amount,avgUtility:x.utilitySum/Math.max(1,x.chunks)})).sort((a,b)=>b.amountBase-a.amountBase);const invested=rows.reduce((s,x)=>s+x.amountBase,0),cash=newTotal-invested,weightedScore=invested?rows.reduce((s,x)=>s+x.amountBase*x.normScore,0)/invested:0,weightedRisk=invested?rows.reduce((s,x)=>s+x.amountBase*x.risk,0)/invested:0,weightedExpected=invested?rows.reduce((s,x)=>s+x.amountBase*x.expected,0)/invested:0,largest=invested?Math.max(...rows.map(x=>x.amountBase))/newTotal*100:0;const families=new Set(rows.map(x=>x.family)).size,sectors=new Set(rows.map(x=>x.sector)).size,riskIndex=allocClamp(weightedRisk/5*80+Math.max(0,largest-20)*.7+(rows.length<3?8:0),0,100);const merit=allocClamp(weightedScore-weightedRisk*5.2+Math.min(8,sectors*1.1)+Math.min(5,families*1.5)+(invested/newTotal*100)*.08,0,100);return{...def,rows,invested,cash,weightedScore,weightedRisk,weightedExpected,riskIndex,largest,families,sectors,merit,total:newTotal,walletRemaining:wallet}}
function allocFundingLabel(row,p,baseInfo){const native=allocFromBase(row.amountBase,row.currency,baseInfo.base,baseInfo.mep);let qty=row.price>0?(['argbond','on'].includes(row.type)?native/row.price*100:native/row.price):NaN;if(['argstock','cedear','stock','argbond','on'].includes(row.type)&&Number.isFinite(qty))qty=Math.floor(qty);return{native,qty}}
