function allocRenderProfiles(profiles,baseInfo){capitalAllocator.profiles=profiles;const box=$('allocatorProfiles');box.innerHTML=['conservative','moderate','aggressive'].map(k=>allocProfileHtml(profiles[k],baseInfo)).join('');globalThis.allocatorReportSync?.();const viable=Object.values(profiles).filter(x=>x.rows.length&&x.invested>0).sort((a,b)=>b.merit-a.merit),best=viable[0];if(best){$('allocRecommendation').classList.add('show');$('allocRecommendedTitle').textContent=best.label;$('allocRecommendedScore').textContent=Math.round(best.merit)+'/100';const delta=best.rows.length?`Invierte ${allocPct(best.invested/best.total*100)} en ${best.rows.length} activos, riesgo ${Math.round(best.riskIndex)}/100 y score normalizado medio ${Math.round(best.weightedScore)}/100.`:'Sin posiciones.';$('allocRecommendedWhy').textContent=`Es el perfil que mejor combina oportunidades, riesgo, diversificación y capacidad de ejecución entre las tres alternativas. ${delta} Es una comparación interna, no una probabilidad de ganancia.`}else{$('allocRecommendation').classList.remove('show')}}
