function allocatorReportSync(preferredKey=''){const ca=globalThis.capitalAllocator||{},select=document.getElementById('allocatorReportProfile'),state=document.getElementById('allocatorReportState'),section=document.getElementById('allocatorClientReport');if(!select||!section)return;const profiles=ca.profiles||null;if(!profiles){select.innerHTML='<option value="">Calculá una propuesta</option>';select.disabled=true;section.classList.add('is-disabled');if(state){state.textContent='SIN PROPUESTA';state.className='alloc-report-state'};for(const id of ['allocatorGenerateReportBtn','allocatorExportExcelBtn','allocatorExportPdfBtn','allocatorBrochureBtn']){const b=document.getElementById(id);if(b)b.disabled=true}return}const keys=['conservative','moderate','aggressive'].filter(k=>profiles[k]);select.innerHTML=keys.map(k=>`<option value="${k}">${allocatorReportEsc(profiles[k].label)}${profiles[k].fullInvestment?'':' · incompleta'}</option>`).join('');const viable=keys.filter(k=>profiles[k].rows?.length&&profiles[k].fullInvestment).sort((a,b)=>(profiles[b].merit||0)-(profiles[a].merit||0));select.value=keys.includes(preferredKey)?preferredKey:(viable[0]||keys[0]||'');select.disabled=!keys.length;section.classList.remove('is-disabled');allocatorReportProfileChanged(false)}
function allocatorReportProfileChanged(render=false){const key=document.getElementById('allocatorReportProfile')?.value||'',s=allocatorReportSnapshot(key),state=document.getElementById('allocatorReportState'),ok=!!(s?.profile?.rows?.length&&s.profile.fullInvestment);for(const id of ['allocatorGenerateReportBtn','allocatorExportExcelBtn','allocatorExportPdfBtn','allocatorBrochureBtn']){const b=document.getElementById(id);if(b)b.disabled=!ok}if(state){state.textContent=ok?'LISTO PARA GENERAR':s?'PROPUESTA INCOMPLETA':'SIN PROPUESTA';state.className=`alloc-report-state ${ok?'ok':'warn'}`}if(render&&ok)allocatorGenerateReport()}
function allocatorGenerateReport(){const key=document.getElementById('allocatorReportProfile')?.value||'',s=allocatorReportSnapshot(key),box=document.getElementById('allocatorReportPreview');if(!s||!s.profile?.fullInvestment){if(box)box.innerHTML='<div class="alloc-report-empty"><b>No hay una cartera final válida para presentar.</b><span>Recalculá o revisá los límites. Radar no genera un brochure comercial de una propuesta incompleta.</span></div>';return false}if(box){box.classList.remove('is-generated');box.innerHTML=allocatorReportPreviewHtml(s);box.dataset.profileKey=key;void box.offsetWidth;box.classList.add('is-generated');box.scrollIntoView({behavior:'smooth',block:'start'})}const state=document.getElementById('allocatorReportState');if(state){state.textContent='INFORME GENERADO';state.className='alloc-report-state ok'}return true}
