async function advisorReleaseLoad(){const features=await g2RuntimeFeatures(),box=$('advisorReleaseCertification');if(box)box.style.display=features?.releaseCertification?'block':'none';if(!features?.releaseCertification)return null;const x=await advisorJson('/api/g2/ops/release/gate'),g=$('advisorReleaseGateChip'),a=$('advisorReleaseApprovalChip');if(g){g.textContent=`Release ${x.status}`;g.className=x.certified?'intel-chip good':x.eligible?'intel-chip warn':'intel-chip bad'}if(a){a.textContent=x.missingApprovalRoles?.length?`Faltan ${x.missingApprovalRoles.join('+')}`:'Approvals OK';a.className=x.missingApprovalRoles?.length?'intel-chip warn':'intel-chip good'}const failed=(x.checks||[]).filter(c=>c.required&&c.status!=='PASS').map(c=>c.code);$('advisorReleaseStatus').textContent=`${x.version} / ${x.phase} · manifest ${String(x.manifestHash||'').slice(0,12)}… · evidence ${String(x.evidenceHash||'').slice(0,12)}… · blockers: ${failed.join(', ')||'ninguno'} · approvals: ${(x.approvals||[]).map(v=>v.actorRole+':'+v.actorId).join(', ')||'ninguna'}. CERTIFIED no despliega automáticamente.`;return x}

