function advisorDeploymentRender(x){const run=x?.run||x?.runs?.[0]||null;if(run)advisorDeploymentCurrentRun=run;const chip=$('advisorDeploymentChip'),status=$('advisorDeploymentStatus'),timeline=$('advisorDeploymentTimeline');if(chip){chip.textContent=run?`Deployment ${run.status}`:'Deployment sin run';chip.className=run?.status==='PROMOTED'?'intel-chip good':run?.status==='ROLLED_BACK'?'intel-chip warn':run&&['ROLLBACK_REQUIRED','STALE'].includes(run.status)?'intel-chip bad':run?'intel-chip warn':'intel-chip neutral'}if(status)status.textContent=run?`${run.version}/${run.phase} · env ${run.environmentId} · run ${run.runId} · manifest ${String(run.manifestHash||'').slice(0,12)}… · snapshot ${run.snapshot?.backupId||'N/D'} · executionMode CONTROL_PLANE_ONLY_EXTERNAL_PROCESS_MUTATION.`:'No hay deployment run. Sólo se puede crear uno cuando el release actual está CERTIFIED.';const events=x?.events||[];if(timeline)timeline.innerHTML=run?(events.length?events.slice().reverse().map(e=>`<div class="advisor-directory-row"><b>${escapeHtml(e.type)}</b><small>${escapeHtml(e.at)} · ${escapeHtml(e.actorId||'')}</small><span>${escapeHtml(e.reason||'')}</span><code>${escapeHtml(String(e.eventHash||'').slice(0,14))}…</code></div>`).join(''):'<div class="alloc-empty">Run sin eventos visibles.</div>'):'<div class="alloc-empty">Deployment timeline N/D.</div>';return run}
async function advisorDeploymentLoad(){const features=await g2RuntimeFeatures(),box=$('advisorDeploymentPromotion');if(box)box.style.display=features?.releasePromotion?'block':'none';if(!features?.releasePromotion)return null;const list=await advisorJson('/api/g2/ops/deployment/runs?limit=20'),run=(list.runs||[])[0];if(!run){advisorDeploymentCurrentRun=null;advisorDeploymentRender(list);await advisorAdapterLoad().catch(()=>{});return list}const x=await advisorJson('/api/g2/ops/deployment/run?id='+encodeURIComponent(run.runId));advisorDeploymentRender(x);await advisorAdapterLoad().catch(()=>{});return x}
async function advisorDeploymentPost(path,body){const x=await advisorJson(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});advisorDeploymentRender(x);return x}
async function advisorDeploymentPlan(){const gate=await advisorReleaseLoad();if(!gate?.certified){$('advisorDeploymentStatus').textContent='Release no CERTIFIED: no se puede crear deployment plan.';return}const environmentId=await window.radarPrompt('Environment ID para el deployment:','production');if(!environmentId)return;const note=await window.radarPrompt('Nota del deployment plan (opcional):','Controlled promotion of certified release');if(note===null)return;if(!await window.radarConfirm(`Crear plan de promoción para ${gate.version}/${gate.phase} en ${environmentId}? Esto NO despliega nada.`))return advisorDeploymentPost('/api/g2/ops/deployment/plan',{environmentId,note,confirmPlan:true})}
async function advisorDeploymentPreflight(){const r=advisorDeploymentCurrentRun;if(!r)return advisorDeploymentLoad();return advisorDeploymentPost('/api/g2/ops/deployment/preflight',{runId:r.runId})}
async function advisorDeploymentMaintenance(){const r=advisorDeploymentCurrentRun;if(!r)return;const startDefault=new Date(Date.now()-60000).toISOString(),endDefault=new Date(Date.now()+2*3600000).toISOString(),startAt=await window.radarPrompt('Inicio ventana mantenimiento (ISO):',startDefault);if(!startAt)return;const endAt=await window.radarPrompt('Fin ventana mantenimiento (ISO):',endDefault);if(!endAt)return;const note=await window.radarPrompt('Nota de maintenance window:','Approved deployment window');if(note===null)return;if(!await window.radarConfirm('Aprobar esta ventana de mantenimiento?'))return;return advisorDeploymentPost('/api/g2/ops/deployment/maintenance',{runId:r.runId,startAt,endAt,note,confirmMaintenance:true})}
async function advisorDeploymentSnapshot(){const r=advisorDeploymentCurrentRun;if(!r)return;if(!await window.radarConfirm('Crear snapshot persistente pre-deployment ahora?'))return;return advisorDeploymentPost('/api/g2/ops/deployment/snapshot',{runId:r.runId,label:`pre-deployment ${r.runId}`,confirmSnapshot:true})}
async function advisorDeploymentRollout(){const r=advisorDeploymentCurrentRun;if(!r)return;const ref=await window.radarPrompt('Referencia de ejecución EXTERNA del rollout (ticket/job/commit/deploy id):','');if(!ref)return;const observedVersion=await window.radarPrompt('Versión observada por el operador después del rollout:',r.version);if(observedVersion===null)return;const observedPhase=await window.radarPrompt('Phase observada:',r.phase);if(observedPhase===null)return;const artifactSha256=await window.radarPrompt('SHA-256 del artefacto desplegado (opcional si la plataforma externa ya lo verificó):','');if(artifactSha256===null)return;if(!await window.radarConfirm('Confirmás que el rollout del proceso fue ejecutado EXTERNAMENTE? Radar sólo registrará la evidencia; no copiará ni reiniciará archivos.'))return;return advisorDeploymentPost('/api/g2/ops/deployment/rollout-record',{runId:r.runId,deploymentReference:ref,manifestHash:r.manifestHash,artifactSha256:artifactSha256||undefined,observedVersion,observedPhase,confirmRollout:true})}
async function advisorDeploymentHealth(){const r=advisorDeploymentCurrentRun;if(!r)return;return advisorDeploymentPost('/api/g2/ops/deployment/verify-health',{runId:r.runId})}
async function advisorDeploymentCertify(){const r=advisorDeploymentCurrentRun;if(!r)return;const note=await window.radarPrompt('Nota post-deployment certification:','Health + release evidence verified after rollout');if(note===null)return;if(!await window.radarConfirm('Marcar PROMOTED sólo si health y release certification siguen vigentes?'))return;return advisorDeploymentPost('/api/g2/ops/deployment/post-certify',{runId:r.runId,note,confirmPromotion:true})}
async function advisorDeploymentRollbackArm(){const r=advisorDeploymentCurrentRun;if(!r)return;const reason=await window.radarPrompt('Motivo del rollback controlado:','Post-deployment verification failed');if(!reason)return;if(!await window.radarConfirm(`Armar rollback hacia ${r.rollback?.version||'?'} / ${r.rollback?.phase||'?'}? Radar verificará el ZIP pero NO lo ejecutará.`))return;return advisorDeploymentPost('/api/g2/ops/deployment/rollback-arm',{runId:r.runId,reason,confirmRollback:true})}
async function advisorDeploymentRollbackRecord(){const r=advisorDeploymentCurrentRun;if(!r||!r.rollback)return;const ref=await window.radarPrompt('Referencia de rollback EXTERNO ejecutado (ticket/job):','');if(!ref)return;if(!await window.radarConfirm(`Confirmás que el rollback externo restauró ${r.rollback.version}/${r.rollback.phase} usando SHA ${String(r.rollback.sha256).slice(0,12)}…?`))return;return advisorDeploymentPost('/api/g2/ops/deployment/rollback-record',{runId:r.runId,rollbackReference:ref,artifactSha256:r.rollback.sha256,observedVersion:r.rollback.version,observedPhase:r.rollback.phase,confirmRollbackRecorded:true})}
async function advisorDeploymentAbort(){const r=advisorDeploymentCurrentRun;if(!r)return;const reason=await window.radarPrompt('Motivo para abortar el deployment plan:','Deployment cancelled before rollout');if(!reason)return;if(!await window.radarConfirm('Abortar este deployment plan?'))return;return advisorDeploymentPost('/api/g2/ops/deployment/abort',{runId:r.runId,reason,confirmAbort:true})}

async function advisorRunnerIdentityLoad(){const x=await advisorJson('/api/g2/ops/deployment/runners'),chip=$('advisorRunnerIdentityChip'),rows=x.directory?.runners||[];if(chip){chip.textContent=`Runner Identity ${x.policy?.enabled?'ON':'OFF'} · ${rows.length} runners`;chip.className=x.policy?.enabled&&rows.some(r=>r.status==='ACTIVE'&&r.keys?.some(k=>k.status==='ACTIVE'))?'intel-chip good':'intel-chip warn'}$('advisorRunnerIdentityList').innerHTML=rows.length?rows.map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.runnerId)}<small>${escapeHtml(r.displayName||'')}</small></b><span>${escapeHtml(r.status)} · ${escapeHtml((r.allowedEnvironmentIds||[]).join(','))}</span><span>${(r.keys||[]).map(k=>`${escapeHtml(k.keyId)}:${escapeHtml(k.status)}:${escapeHtml(String(k.fingerprintSha256||'').slice(0,10))}…`).join(' · ')||'sin keys'}</span></div>`).join(''):'<div class="alloc-empty">Sin runner identities provisionados.</div>';await advisorRunnerFleetLoad().catch(()=>{});return x}
async function advisorRunnerFleetLoad(){const features=await g2RuntimeFeatures();if(!features?.deploymentRunnerFleetGovernance)return null;const x=await advisorJson('/api/g2/ops/deployment/runner-fleet'),chip=$('advisorRunnerFleetChip'),rows=x.runners||[];if(chip){const blocked=rows.filter(r=>r.status==='BLOCKED').length,warn=rows.filter(r=>r.status==='DEGRADED').length;chip.textContent=`Fleet ${blocked?'BLOCKED':warn?'DEGRADED':'READY'} · ${rows.length}`;chip.className=blocked?'intel-chip bad':warn?'intel-chip warn':'intel-chip good'}const p=x.policy||{},required=(p.requiredOnboardingApprovalRoles||[]).join('+')||'N/D';$('advisorRunnerFleetStatus').textContent=`Onboarding approvals ${required} · min runner ${p.minRunnerVersion||'N/D'} · max key age ${p.maxKeyAgeDays??'N/D'}d · hardware verified=${p.requireHardwareVerified?'required':'optional'} · verifier: declaraciones TPM/HSM/KMS no cuentan como VERIFIED sin verifier real.`;$('advisorRunnerFleetList').innerHTML=rows.length?rows.map(r=>{const o=r.onboarding,missing=(p.requiredOnboardingApprovalRoles||[]).filter(role=>!(o?.approvals||[]).some(a=>a.actorRole===role));return `<div class="advisor-directory-row"><b>${escapeHtml(r.runnerId)}<small>${escapeHtml(r.status)}</small></b><span>onboarding ${escapeHtml(o?.status||'MISSING')} · faltan ${escapeHtml(missing.join('+')||'ninguno')}</span><span>keys ${r.activeKeyCount||0} · oldest ${r.oldestActiveKeyAgeDays==null?'N/D':Number(r.oldestActiveKeyAgeDays).toFixed(1)+'d'}</span></div>`}).join(''):'<div class="alloc-empty">Sin runners en fleet.</div>';const audit=x.recentAudit||[];$('advisorRunnerAuditList').innerHTML=audit.length?audit.slice(0,40).map(a=>`<div class="advisor-directory-row"><b>${escapeHtml(a.runnerId)}<small>${escapeHtml(a.decision)}</small></b><span>${escapeHtml(a.runnerVersion)} · ${escapeHtml(a.platform)}/${escapeHtml(a.architecture)} · ${escapeHtml(a.hardwareBinding?.verification||'NO_HW')} · supply ${escapeHtml(a.supplyChainStatus||'N/D')}</span><span>${escapeHtml((a.reasons||[]).join(' | ')||'PASS')}</span></div>`).join(''):'<div class="alloc-empty">Sin attestations auditadas.</div>';await advisorRunnerTrustLoad().catch(()=>{});return x}
async function advisorRunnerOnboardingRequest(){const runnerId=$('advisorRunnerId')?.value?.trim();if(!runnerId)return;await advisorJson('/api/g2/ops/deployment/runner-fleet/onboarding/request',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runnerId,reason:'requested from Radar UI',confirmRequest:true})});await advisorRunnerFleetLoad()}
async function advisorRunnerOnboardingDecision(decision){const runnerId=$('advisorRunnerId')?.value?.trim(),actorRole=$('advisorRunnerOnboardingRole')?.value||'ADMIN';if(!runnerId)return;const reason=await window.radarPrompt(`${decision} onboarding ${runnerId} — motivo obligatorio:`,decision==='APPROVE'?'fleet onboarding approved':'fleet onboarding decision');if(!reason)return;if(!await window.radarConfirm(`${decision} onboarding ${runnerId} como ${actorRole}?`))return;await advisorJson('/api/g2/ops/deployment/runner-fleet/onboarding/decision',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runnerId,decision,actorRole,reason,confirmDecision:true})});await advisorRunnerFleetLoad()}
async function advisorRunnerTrustLoad(){const features=await g2RuntimeFeatures();const panel=$('advisorRunnerTrustPanel');if(panel)panel.style.display=features?.deploymentRunnerTrust?'block':'none';if(!features?.deploymentRunnerTrust)return null;const x=await advisorJson('/api/g2/ops/deployment/runner-trust'),chip=$('advisorRunnerTrustChip'),roots=x.roots||[],releases=x.softwareReleases||[],p=x.policy||{},activeRoots=roots.filter(r=>r.status==='ACTIVE').length,approved=releases.filter(r=>r.status==='APPROVED').length;if(chip){chip.textContent=`Trust ${activeRoots} roots · ${approved} releases`;chip.className=(p.requireApprovedSoftwareRelease&&approved===0)?'intel-chip bad':'intel-chip good'}$('advisorRunnerTrustStatus').textContent=`approved release=${p.requireApprovedSoftwareRelease?'required':'optional'} · SBOM=${p.requireSbom?'required':'optional'} · provenance=${p.requireProvenance?'required':'optional'} · signed hardware evidence=${p.requireSignedHardwareEvidence?'required':'optional'} · transparency checkpoint=${p.requireTransparencyCheckpoint?'required':'optional'} · max release age ${p.maxSoftwareReleaseAgeDays??'N/D'}d. SIGNED_EVIDENCE_VERIFIED no equivale a hardware VERIFIED.`;$('advisorRunnerTrustList').innerHTML=(roots.length||releases.length)?roots.map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.rootId)}<small>${escapeHtml(r.kind)}</small></b><span>${escapeHtml(r.status)} · ${escapeHtml(String(r.fingerprintSha256||'').slice(0,16))}…</span><span>${escapeHtml(r.validUntil||'sin expiry')}</span></div>`).join('')+releases.map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.releaseId)}<small>${escapeHtml(r.status)}</small></b><span>${escapeHtml(r.runnerVersion)} · ${escapeHtml(r.platform)}/${escapeHtml(r.architecture)}</span><span>binary ${escapeHtml(String(r.binarySha256||'').slice(0,12))}… · root ${escapeHtml(r.signingRootId||'N/D')}</span></div>`).join(''):'<div class="alloc-empty">Sin trust roots ni runner releases registrados.</div>';await advisorRunnerTransparencyLoad().catch(()=>{});await advisorRunnerVendorTrustLoad().catch(()=>{});await advisorRunnerVendorMetadataLoad().catch(()=>{});await advisorRunnerExternalTransparencyLoad().catch(()=>{});await advisorRunnerExternalConnectorLoad().catch(()=>{});await advisorRunnerGovernanceLoad().catch(()=>{});return x}
async function advisorRunnerTransparencyLoad(){const features=await g2RuntimeFeatures();if(!features?.deploymentRunnerTransparency)return null;const x=await advisorJson('/api/g2/ops/deployment/runner-transparency'),chip=$('advisorRunnerTransparencyChip'),entries=x.entries||[],checkpoints=x.checkpoints||[];if(chip){chip.textContent=`Transparency ${entries.length} entries · ${checkpoints.length} checkpoints`;chip.className=(x.policy?.requireCheckpointForSoftware&&checkpoints.length===0)?'intel-chip bad':'intel-chip good'}return x}
async function advisorRunnerTransparencyCheckpointRegister(){const raw=$('advisorRunnerTransparencyCheckpointJson')?.value?.trim();if(!raw)return;let req;try{req=JSON.parse(raw)}catch{throw new Error('Signed transparency checkpoint JSON inválido')}if(!req.signedCheckpoint)req={signedCheckpoint:req,confirmRegister:true};req.confirmRegister=true;await advisorJson('/api/g2/ops/deployment/runner-transparency/checkpoints/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(req)});await advisorRunnerTransparencyLoad()}
async function advisorRunnerVendorTrustLoad(){const features=await g2RuntimeFeatures();if(!features?.deploymentRunnerVendorAttestation)return null;const x=await advisorJson('/api/g2/ops/deployment/runner-vendor-trust'),chip=$('advisorRunnerVendorTrustChip'),roots=x.roots||[],active=roots.filter(r=>r.status==='ACTIVE').length;if(chip){chip.textContent=`Vendor X.509 ${active}/${roots.length} active`;chip.className=roots.length&&active===roots.length?'intel-chip good':roots.length?'intel-chip warn':'intel-chip neutral'}$('advisorRunnerVendorTrustStatus').textContent=`profiles ${(x.policy?.profiles||[]).length} · native vendor attestation=${x.policy?.enabled?'enabled':'disabled'} · roots se validan por fingerprint/subject/issuer/validity y nunca exponen PEM en status.`;$('advisorRunnerVendorTrustList').innerHTML=roots.length?roots.map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.rootId)}<small>${escapeHtml(r.vendor)}</small></b><span>${escapeHtml(r.status)} · ${escapeHtml(String(r.fingerprintSha256||'').slice(0,16))}…</span><span>${escapeHtml(r.subject||'')} · exp ${escapeHtml(r.validUntil||'N/D')}</span></div>`).join(''):'<div class="alloc-empty">Sin vendor X.509 roots registradas.</div>';return x}
async function advisorRunnerVendorRootSave(){const rootId=$('advisorRunnerVendorRootId')?.value?.trim(),vendor=$('advisorRunnerVendor')?.value,certificatePem=$('advisorRunnerVendorCertificatePem')?.value?.trim();if(!rootId||!vendor||!certificatePem)return;if(certificatePem.includes('PRIVATE KEY')){$('advisorRunnerVendorTrustStatus').textContent='Rechazado: nunca pegues una private key en Radar.';return}await advisorJson('/api/g2/ops/deployment/runner-vendor-trust/roots/upsert',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({rootId,vendor,certificatePem})});$('advisorRunnerVendorCertificatePem').value='';await advisorRunnerVendorTrustLoad()}
