async function advisorRunnerVendorMetadataLoad(){const features=await g2RuntimeFeatures();if(!features?.deploymentVendorMetadataSync)return null;const x=await advisorJson('/api/g2/ops/deployment/runner-vendor-metadata'),chip=$('advisorRunnerVendorMetadataChip'),rows=x.candidates||[],pending=rows.filter(r=>r.status==='PENDING_REVIEW').length,alerts=rows.filter(r=>r.status==='REVOCATION_ALERT').length,evalx=x.activeTrustEvaluation||{};if(chip){chip.textContent=`Metadata ${evalx.status||'N/D'} · ${pending} pending · ${alerts} revoke`;chip.className=evalx.status==='BLOCKED'?'intel-chip bad':evalx.status==='READY'?'intel-chip good':'intel-chip warn'}const sources=x.sources||[];if(!$('advisorRunnerVendorMetadataSourceId')?.value&&sources.length)$('advisorRunnerVendorMetadataSourceId').value=sources[0].sourceId;$('advisorRunnerVendorMetadataStatus').textContent=`sync=${x.policy?.enabled?'enabled':'disabled'} · fresh required=${x.policy?.requireFreshMetadata?'yes':'no'} · signed revocation blocks=${x.policy?.blockOnSignedRevocation?'yes':'no'} · sources ${sources.length}. URLs quedan fuera de la UI.`;$('advisorRunnerVendorMetadataList').innerHTML=rows.length?rows.slice().reverse().map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.rootId)}<small>${escapeHtml(r.vendor)} · ${escapeHtml(r.status)}</small></b><span>${escapeHtml(r.state)} · ${escapeHtml(String(r.fingerprintSha256||'').slice(0,18))}…</span><span>${r.status==='PENDING_REVIEW'?`<button type="button" class="secondary-action" data-vmeta-approve="${escapeHtml(r.candidateId)}" data-vmeta-sha="${escapeHtml(r.candidateSha256)}">Aprobar</button> <button type="button" class="secondary-action" data-vmeta-reject="${escapeHtml(r.candidateId)}" data-vmeta-sha="${escapeHtml(r.candidateSha256)}">Rechazar</button>`:r.status==='REVOCATION_ALERT'?'Revocation alert: usar Revocar vendor root tras revisión':escapeHtml(r.reviewNote||r.reason||'')}</span></div>`).join(''):'<div class="alloc-empty">Sin candidatos de metadata.</div>';document.querySelectorAll('[data-vmeta-approve]').forEach(b=>b.addEventListener('click',()=>advisorRunnerVendorMetadataApprove(b.getAttribute('data-vmeta-approve'),b.getAttribute('data-vmeta-sha')).catch(e=>{$('advisorRunnerVendorMetadataStatus').textContent=String(e.message||e)})));document.querySelectorAll('[data-vmeta-reject]').forEach(b=>b.addEventListener('click',()=>advisorRunnerVendorMetadataReject(b.getAttribute('data-vmeta-reject'),b.getAttribute('data-vmeta-sha')).catch(e=>{$('advisorRunnerVendorMetadataStatus').textContent=String(e.message||e)})));return x}
async function advisorRunnerVendorMetadataPoll(jobId){for(let i=0;i<40;i++){await new Promise(r=>setTimeout(r,500));const j=await advisorJson('/api/g2/ops/deployment/runner-vendor-metadata/jobs?jobId='+encodeURIComponent(jobId));$('advisorRunnerVendorMetadataStatus').textContent=`Sync ${j.status} · ${j.sourceId}${j.error?' · '+j.error:''}`;if(j.status==='SUCCEEDED'||j.status==='FAILED'){await advisorRunnerVendorMetadataLoad();return j}}throw new Error('Vendor metadata sync sigue RUNNING; usá Metadata para refrescar estado')}
