async function advisorRunnerExternalTransparencyLoad(){const features=await g2RuntimeFeatures();if(!features?.deploymentExternalTransparency)return null;const x=await advisorJson('/api/g2/ops/deployment/runner-external-transparency'),chip=$('advisorRunnerExternalTransparencyChip'),rows=x.receipts||[];if(chip){chip.textContent=`External anchors ${rows.length}`;chip.className=(x.policy?.requireAnchorForSoftware&&rows.length===0)?'intel-chip bad':rows.length?'intel-chip good':'intel-chip neutral'}$('advisorRunnerExternalTransparencyStatus').textContent=`external anchoring=${x.policy?.enabled?'enabled':'disabled'} · required=${x.policy?.requireAnchorForSoftware?'yes':'no'} · max age ${x.policy?.maxAnchorAgeHours??'N/D'}h · allowed logs ${(x.policy?.allowedExternalLogIds||[]).join(',')||'any explicitly signed log'}.`;$('advisorRunnerExternalTransparencyList').innerHTML=rows.length?rows.slice().reverse().map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.anchorId)}<small>${escapeHtml(r.externalLogId)}</small></b><span>checkpoint ${escapeHtml(r.checkpointId)} · seq ${escapeHtml(String(r.anchorSequence))}</span><span>${escapeHtml(r.anchoredAt)} · root ${escapeHtml(r.signingRootId)}</span></div>`).join(''):'<div class="alloc-empty">Sin external anchor receipts.</div>';return x}
async function advisorRunnerExternalAnchorRegister(){const raw=$('advisorRunnerExternalAnchorJson')?.value?.trim();if(!raw)return;let req;try{req=JSON.parse(raw)}catch{throw new Error('Signed external transparency receipt JSON inválido')}if(!req.signedReceipt)req={signedReceipt:req,confirmRegister:true};req.confirmRegister=true;await advisorJson('/api/g2/ops/deployment/runner-external-transparency/anchors/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(req)});$('advisorRunnerExternalAnchorJson').value='';await advisorRunnerExternalTransparencyLoad()}
