async function advisorAdapterLoad(){const features=await g2RuntimeFeatures(),box=$('advisorDeploymentAutomation');if(box)box.style.display=features?.deploymentAutomation?'block':'none';const rib=$('advisorRunnerIdentityPanel');if(rib)rib.style.display=features?.deploymentRunnerIdentity?'block':'none';if(!features?.deploymentAutomation)return null;const x=await advisorJson('/api/g2/ops/deployment/adapters'),ready=(x.adapters||[]).filter(a=>a.canExecute).map(a=>a.type),runner=x.runnerProtocol,identity=runner?.runnerIdentity;const chip=$('advisorAdapterChip');if(chip){chip.textContent=`Adapters ${x.policy?.executionEnabled?'EXEC':'DRY'} · ${runner?.enabled?'Runner 8S':'Legacy 8R'}`;chip.className=x.policy?.hmacConfigured&&(!runner||runner.ackHmacConfigured)?'intel-chip good':'intel-chip warn'}if(runner?.artifactRegistry?.verified){const a=(runner.artifactRegistry.registry?.artifacts||[]).find(v=>v.kind==='RELEASE_BUNDLE');if(a&&$('advisorAdapterArtifactId')&&!$('advisorAdapterArtifactId').value)$('advisorAdapterArtifactId').value=a.artifactId}if(features?.deploymentRunnerProtocol&&advisorDeploymentCurrentRun){const l=await advisorJson('/api/g2/ops/deployment/lease?environmentId='+encodeURIComponent(advisorDeploymentCurrentRun.environmentId)).catch(()=>null);if(l?.lease&&$('advisorAdapterLeaseId'))$('advisorAdapterLeaseId').value=l.lease.leaseId}if(runner?.requireSignedAcknowledgement)$('advisorAdapterAckBtn').disabled=true;$('advisorAdapterStatus').textContent=`execution=${!!x.policy?.executionEnabled} · handoff HMAC=${x.policy?.hmacConfigured?'OK':'faltante'} · runner=${identity?.policy?.enabled?'8T':runner?.enabled?'8S':'8R'} · identity=${identity?.policy?.enabled?'Ed25519':'legacy'} · ack HMAC=${identity?.policy?.enabled?'legacy-only':runner?.ackHmacConfigured?'OK':'N/D'} · artifact registry=${runner?.artifactRegistry?.verified?'OK':'N/D'} · runners=${runner?.allowedRunnerIds?.join(',')||'N/D'}.`;return x}
