async function advisorAdapterLease(action){const r=advisorDeploymentCurrentRun;if(!r)return;let path,body;if(action==='acquire'){path='/api/g2/ops/deployment/lease-acquire';body={runId:r.runId,environmentId:r.environmentId,confirmAcquire:true}}else{const leaseId=$('advisorAdapterLeaseId')?.value?.trim();if(!leaseId)return;path=action==='renew'?'/api/g2/ops/deployment/lease-renew':'/api/g2/ops/deployment/lease-release';body=action==='renew'?{leaseId,confirmRenew:true}:{leaseId,confirmRelease:true}}const x=await advisorJson(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(x.leaseId)$('advisorAdapterLeaseId').value=x.leaseId;$('advisorAdapterStatus').textContent=`Lease ${x.status||'ACTIVE'} · core ${x.ownerCoreId||'N/D'} · fencing ${x.fencingToken??'N/D'} · exp ${x.expiresAt||'N/D'}.`;return x}
async function advisorAdapterRollback(dispatch){const r=advisorDeploymentCurrentRun;if(!r)return;const adapter=$('advisorAdapterType')?.value||'FILE_HANDOFF',artifactId=$('advisorAdapterArtifactId')?.value?.trim(),artifactReference=$('advisorAdapterArtifactRef')?.value?.trim()||undefined;if(!artifactId)throw new Error('Artifact ID rollback requerido');if(dispatch&&!await window.radarConfirm('Dispatch rollback 8S? Requiere ROLLBACK_ARMED, lease activo, artifact rollback registrado y ACK firmado.'))return;const path=dispatch?'/api/g2/ops/deployment/rollback-adapter-dispatch':'/api/g2/ops/deployment/rollback-adapter-dry-run',x=await advisorJson(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({runId:r.runId,adapter,artifactId,artifactReference,confirmDispatch:dispatch})});$('advisorAdapterExecutionId').value=x.execution?.executionId||'';$('advisorAdapterStatus').textContent=`Rollback ${x.execution?.status||'N/D'} · artifact=${x.execution?.artifactId||'N/D'} · fencing=${x.execution?.leaseFencingToken??'N/D'}.`;return x}
async function advisorAdapterAck(){const r=advisorDeploymentCurrentRun,executionId=$('advisorAdapterExecutionId')?.value?.trim();if(!r||!executionId)return;const deploymentReference=await window.radarPrompt('Referencia del deployment ejecutado por el runner externo:','');if(!deploymentReference)return;const observedVersion=await window.radarPrompt('Versión observada:',r.version);if(observedVersion===null)return;const observedPhase=await window.radarPrompt('Phase observada:',r.phase);if(observedPhase===null)return;const artifactSha256=await window.radarPrompt('Artifact SHA-256 (opcional):','');if(artifactSha256===null)return;if(!await window.radarConfirm('Registrar acknowledgement autenticado del runner externo? En stage final esto alimentará rollout-record de 8Q.'))return;const x=await advisorJson('/api/g2/ops/deployment/adapter-acknowledge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({executionId,deploymentReference,observedVersion,observedPhase,artifactSha256:artifactSha256||undefined,confirmAcknowledge:true})});$('advisorAdapterStatus').textContent=`ACK ${x.execution?.status||'N/D'} · stage ${x.execution?.stage||'N/D'} · rolloutRecorded=${x.rolloutRecorded?'sí':'no'} · next=${x.nextStage||'final'}.`;if(x.rolloutRecorded)await advisorDeploymentLoad();return x}
