const advisorG2State={domain:null,loading:false,dashboard:null,monitoring:false,workflowRecommendationId:null,security:null,directory:null,identityProvider:null,actions:null,candidates:null,reviewPlans:null,meetingOutcomes:null};
window.advisorG2State=advisorG2State;
async function advisorJson(url,options={}){const r=await fetch(url,options);const text=await r.text();let body={};try{body=text?JSON.parse(text):{}}catch{body={message:text}}if(!r.ok)throw new Error(body.message||body.error||`HTTP ${r.status}`);return body}
function advisorSecurityHas(permission){return !!advisorG2State.security?.principal?.permissions?.includes(permission)}
function advisorSecurityApply(me){advisorG2State.security=me;const p=me?.principal,chip=$('advisorSecurityIdentity');if(!me?.enabled||!p){if(chip){chip.textContent='Security legacy';chip.className='intel-chip warn'}return}if(chip){chip.textContent=`${p.displayName||p.userId} · ${p.roles?.join('/')||'N/D'} · ${p.organizationId}`;chip.className='intel-chip good'}if($('advisorWorkflowActorId')){$('advisorWorkflowActorId').value=p.userId||'';$('advisorWorkflowActorId').readOnly=true}if($('advisorWorkflowRole')){const role=(p.roles||[]).find(x=>['ADMIN','COMPLIANCE','ADVISOR','ASSISTANT','READ_ONLY'].includes(x))||'READ_ONLY';$('advisorWorkflowRole').value=role;$('advisorWorkflowRole').disabled=true}if($('advisorOrgId')){$('advisorOrgId').value=p.organizationId||'';$('advisorOrgId').readOnly=true}const gate=(id,permission)=>{const el=$(id);if(el)el.disabled=!advisorSecurityHas(permission)};gate('advisorSaveBtn','ADVISOR_DOMAIN_WRITE');gate('advisorLinkPortfolioBtn','ADVISOR_DOMAIN_WRITE');gate('advisorMonitorAllBtn','ADVISOR_MONITOR_READ');gate('advisorCandidatesBtn','ADVISOR_MONITOR_READ');gate('advisorReviewPlansBtn','ADVISOR_MONITOR_READ');gate('advisorMeetingOutcomesBtn','ADVISOR_MONITOR_READ');gate('advisorPersonalizeBtn','ADVISOR_DOMAIN_READ');gate('advisorRecommendationsBtn','RECOMMENDATION_GENERATE');gate('advisorWorkflowRevalidateBtn','WORKFLOW_REVALIDATE');gate('advisorWorkflowAcceptBtn','WORKFLOW_ACCEPT');gate('advisorWorkflowDismissBtn','WORKFLOW_DISMISS');gate('advisorWorkflowNoteBtn','WORKFLOW_NOTE');gate('advisorWorkflowBulkRevalidateBtn','WORKFLOW_REVALIDATE');gate('advisorWorkflowBulkAcceptBtn','WORKFLOW_ACCEPT');gate('advisorWorkflowBulkDismissBtn','WORKFLOW_DISMISS');gate('advisorWorkflowExportBtn','WORKFLOW_EXPORT');gate('advisorProductionRefreshBtn','OPS_READINESS_READ');gate('advisorBackupCreateBtn','OPS_BACKUP_ADMIN');gate('advisorBackupRestoreBtn','OPS_BACKUP_ADMIN');gate('advisorPostgresProbeBtn','OPS_PERSISTENCE_ADMIN');gate('advisorPostgresSyncBtn','OPS_PERSISTENCE_ADMIN');gate('advisorPostgresReconcileBtn','OPS_PERSISTENCE_READ');gate('advisorPostgresRepairBtn','OPS_PERSISTENCE_ADMIN');gate('advisorTelemetryExportBtn','OPS_TELEMETRY_READ')}
async function advisorSecurityLoad(features){if(!features?.security){advisorSecurityApply({enabled:false});return null}try{const me=await advisorJson('/api/g2/security/me');advisorSecurityApply(me);return me}catch(e){advisorG2State.security=null;const chip=$('advisorSecurityIdentity');if(chip){chip.textContent='Security error';chip.className='intel-chip bad'}throw e}}
function advisorOidcRender(provider,session,features){const cfg=provider?.oidc||{},chip=$('advisorOidcSessionChip'),status=$('advisorOidcStatus');if(chip){chip.textContent=session?.active?`OIDC ${session.principal?.displayName||session.principal?.userId||'active'}`:cfg.configured?'OIDC listo · sin sesión':'OIDC no configurado';chip.className=session?.active?'intel-chip good':cfg.configured?'intel-chip warn':'intel-chip neutral'}if(status)status.textContent=session?.active?`Sesión federada activa · ${session.principal?.organizationId||''} · roles ${(session.principal?.roles||[]).join(', ')} · expira ${session.expiresAt||'N/D'}. Roles resueltos desde PERSISTED_MEMBERSHIP.`:cfg.configured?`OIDC ${cfg.profile||'GENERIC_OIDC'} configurado para ${cfg.issuer||''}. Production gate ${cfg.productionMode?(cfg.productionReady?'READY':'BLOCKED'):'DEV'}.`:'Definí issuer/client ID o perfil Entra + tenant/client ID antes de iniciar Phase 8I para activar federation.';if($('advisorOidcIssuer')&&!$('advisorOidcIssuer').value)$('advisorOidcIssuer').value=cfg.issuer||'';if($('advisorOidcLoginBtn'))$('advisorOidcLoginBtn').disabled=!features?.oidcFederation||!cfg.configured||!!session?.active;if($('advisorOidcLogoutBtn'))$('advisorOidcLogoutBtn').disabled=!session?.active;if($('advisorOidcLinkBtn'))$('advisorOidcLinkBtn').disabled=!advisorDirectoryCanWrite()}
async function advisorOidcLogin(){const org=advisorG2State.security?.principal?.organizationId||$('advisorDirectoryOrg')?.value||$('advisorOrgId')?.value;if(!org){$('advisorOidcStatus').textContent='No hay organization autenticada para iniciar SSO.';return}const x=await advisorJson('/api/g2/auth/oidc/start?organizationId='+encodeURIComponent(org));if(!x.authorizationUrl)throw new Error('OIDC authorization URL no disponible');location.assign(x.authorizationUrl)}
async function advisorOidcLogout(){const x=await advisorJson('/api/g2/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(x?.idpLogoutUrl){location.assign(x.idpLogoutUrl);return}location.reload()}
async function advisorOidcLink(){const me=advisorG2State.security?.principal,userId=$('advisorDirectoryUserId')?.value.trim(),subject=$('advisorOidcSubject')?.value.trim(),issuer=$('advisorOidcIssuer')?.value.trim(),email=$('advisorOidcEmail')?.value.trim();if(!userId||!subject||!issuer){$('advisorDirectoryStatus').textContent='Completá userId, OIDC subject e issuer.';return}await advisorJson('/api/g2/security/identities/link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({userId,organizationId:me?.organizationId||$('advisorDirectoryOrg')?.value,provider:'OIDC_FEDERATED',subject,issuer,email:email||undefined})});$('advisorDirectoryStatus').textContent='Identidad OIDC vinculada. El próximo login federado resolverá roles desde la membership persistida.';await advisorIdentityDirectoryLoad()}
function advisorDirectoryCanWrite(){return advisorSecurityHas('SECURITY_DIRECTORY_WRITE')&&advisorSecurityHas('SECURITY_MEMBERSHIP_ADMIN')}
function advisorDirectoryRender(x,provider){advisorG2State.directory=x;advisorG2State.identityProvider=provider;const panel=$('advisorIdentityDirectoryPanel');if(panel)panel.style.display='block';const snap=x?.snapshot||{},me=advisorG2State.security?.principal,rolesAuth=x?.rolesAuthoritativeFrom||advisorG2State.security?.directory?.rolesAuthoritativeFrom||'N/D';$('advisorIdentityProviderChip').textContent=`IdP ${provider?.kind||advisorG2State.security?.directory?.provider||'N/D'}${provider?.active===false?' · inactive':''}`;$('advisorIdentityProviderChip').className=provider?.active===false?'intel-chip warn':'intel-chip good';$('advisorDirectoryRevisionChip').textContent=`Directory rev ${Number(snap.revision)||0}`;$('advisorRoleAuthorityChip').textContent=`Roles: ${rolesAuth}`;$('advisorDirectoryOrg').value=me?.organizationId||'';const canWrite=advisorDirectoryCanWrite(),box=$('advisorDirectoryAdminBox');if(box)box.style.display=canWrite?'block':'none';const memberships=snap.memberships||[],users=new Map((snap.users||[]).map(u=>[String(u.userId),u]));$('advisorDirectoryList').innerHTML=memberships.length?memberships.map(m=>{const u=users.get(String(m.userId))||{};return `<div class="advisor-directory-row ${String(m.status||'').toLowerCase()}"><b>${escapeHtml(u.displayName||String(m.userId))}<small>${escapeHtml(String(m.userId))}</small></b><span>${escapeHtml((m.roles||[]).join(', '))}</span><span>${escapeHtml(String(m.organizationId||''))}</span><span>${escapeHtml(m.status||'')}</span></div>`}).join(''):'<div class="alloc-empty">No hay memberships visibles en este tenant.</div>'}
