function advisorFederationRender(health,tenants,sessions,session){const hc=$('advisorFederationHealthChip');if(hc){hc.textContent=`Federation ${health?.status||'N/D'}`;hc.className=health?.status==='READY'?'intel-chip good':health?.status==='BLOCKED'?'intel-chip bad':health?.status==='DEGRADED'?'intel-chip warn':'intel-chip neutral'}const list=tenants?.tenants||[],sel=$('advisorTenantSelect'),active=tenants?.activeOrganizationId||session?.principal?.organizationId||'';if(sel){sel.innerHTML=list.length?list.map(t=>`<option value="${escapeHtml(String(t.organizationId))}" ${String(t.organizationId)===String(active)?'selected':''}>${escapeHtml(String(t.organizationId))} · ${(t.roles||[]).map(escapeHtml).join(', ')}</option>`).join(''):'<option value="">Sin memberships activas</option>'}if($('advisorTenantSwitchBtn'))$('advisorTenantSwitchBtn').disabled=!session?.active||list.length<2;if($('advisorFederationStatus'))$('advisorFederationStatus').textContent=`${health?.profile||'OIDC'} · ${health?.status||'N/D'} · ${health?.activeSessionCount??0} sesión(es) · production ${health?.productionMode?(health?.productionReady?'READY':'BLOCKED'):'DEV'}. ${(health?.warnings||[]).join(' ')}`;const rows=sessions?.sessions||[],canRevoke=advisorSecurityHas('SECURITY_SESSION_ADMIN');$('advisorSessionList').innerHTML=rows.length?rows.map(x=>`<div class="advisor-directory-row"><b>${escapeHtml(x.displayName||x.userId)}<small>${escapeHtml(x.userId)}</small></b><span>${escapeHtml(String(x.organizationId))}</span><span>${escapeHtml(new Date(x.lastSeenAt).toLocaleString('es-AR'))}</span><span>${canRevoke?`<button class="secondary-action advisor-session-revoke" data-session="${escapeHtml(x.sessionId)}">Revocar</button>`:'activa'}</span></div>`).join(''):'<div class="alloc-empty">No hay sesiones OIDC visibles en este tenant.</div>';document.querySelectorAll('.advisor-session-revoke').forEach(b=>b.addEventListener('click',()=>advisorRevokeSession(b.dataset.session||'').catch(e=>{$('advisorFederationStatus').textContent=String(e.message||e)})))}
async function advisorFederationOpsLoad(features,session){features=features||await g2RuntimeFeatures();if(!features?.federationOperations){$('advisorFederationOps').style.display='none';return null}$('advisorFederationOps').style.display='block';const health=await advisorJson('/api/g2/security/federation-health').catch(e=>({status:'BLOCKED',warnings:[String(e.message||e)]})),tenants=await advisorJson('/api/g2/security/tenants').catch(()=>({tenants:[],count:0})),sessions=advisorSecurityHas('SECURITY_SESSION_READ')?await advisorJson('/api/g2/security/sessions').catch(()=>({sessions:[],count:0})):({sessions:[],count:0});advisorFederationRender(health,tenants,sessions,session);return{health,tenants,sessions}}
async function advisorTenantSwitch(){const org=$('advisorTenantSelect')?.value;if(!org)return;const x=await advisorJson('/api/g2/auth/tenant-switch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({organizationId:org})});$('advisorFederationStatus').textContent=`Tenant activo: ${x.organizationId}. Recargando contexto…`;location.reload()}
async function advisorRevokeSession(sessionId){if(!sessionId||!advisorSecurityHas('SECURITY_SESSION_ADMIN'))return;await advisorJson('/api/g2/security/sessions/revoke',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId})});await advisorFederationOpsLoad(await g2RuntimeFeatures(),await advisorJson('/api/g2/auth/session').catch(()=>({active:false})))}
function advisorProductionRender(readiness,persistence,metrics,backups){const rc=$('advisorReadinessChip'),pc=$('advisorPersistenceChip');if(rc){rc.textContent=`Deployment ${readiness?.status||'N/D'}`;rc.className=readiness?.status==='READY'?'intel-chip good':readiness?.status==='BLOCKED'?'intel-chip bad':'intel-chip warn'}if(pc){pc.textContent=`${persistence?.activeBackend||'N/D'} → ${persistence?.targetBackend||'N/D'}`;pc.className=persistence?.postgresConfigured?'intel-chip warn':'intel-chip neutral'}const fail=(readiness?.checks||[]).filter(x=>x.status==='FAIL').map(x=>x.code),warn=(readiness?.checks||[]).filter(x=>x.status==='WARN').map(x=>x.code);$('advisorProductionStatus').textContent=`${readiness?.productionMode?'PRODUCTION':'LOCAL/DEV'} · ${readiness?.status||'N/D'} · fail: ${fail.join(', ')||'ninguno'} · warn: ${warn.join(', ')||'ninguno'} · requests ${metrics?.requests??0}, 401 ${metrics?.unauthorized401??0}, 403 ${metrics?.forbidden403??0}. PostgreSQL: ${persistence?.migrationStatus||'N/D'}; conexión intentada=${persistence?.postgresConnectionAttempted===true?'sí':'no'}.`;const rows=backups?.backups||[];$('advisorBackupList').innerHTML=rows.length?rows.map(b=>`<div class="advisor-directory-row"><b>${escapeHtml(b.backupId)}<small>${escapeHtml(b.label||'sin etiqueta')}</small></b><span>${escapeHtml(new Date(b.createdAt).toLocaleString('es-AR'))}</span><span>${Number(b.fileCount)||0} stores</span><span>${escapeHtml(String(b.bundleSha256||'').slice(0,12))}…</span></div>`).join(''):'<div class="alloc-empty">No hay backups persistentes todavía.</div>'}
async function advisorProductionOpsLoad(features){features=features||await g2RuntimeFeatures();const panel=$('advisorProductionOps');if(!features?.productionOperations){if(panel)panel.style.display='none';return null}panel.style.display='block';const readiness=advisorSecurityHas('OPS_READINESS_READ')?await advisorJson('/api/g2/ops/readiness').catch(e=>({status:'BLOCKED',checks:[],warnings:[String(e.message||e)]})):null,persistence=advisorSecurityHas('OPS_PERSISTENCE_READ')?await advisorJson('/api/g2/ops/persistence').catch(()=>null):null,metrics=advisorSecurityHas('OPS_SECURITY_METRICS_READ')?await advisorJson('/api/g2/ops/security-metrics').catch(()=>null):null,backups=advisorSecurityHas('OPS_BACKUP_ADMIN')?await advisorJson('/api/g2/ops/backups').catch(()=>({backups:[],count:0})):({backups:[],count:0});advisorProductionRender(readiness,persistence,metrics,backups);if(features?.postgresPersistence)await advisorPostgresOpsLoad(features).catch(()=>{});return{readiness,persistence,metrics,backups}}
function advisorPostgresRender(status,reconcile,gate,telemetry,domains,durable){const pg=status?.postgres||status,pc=$('advisorPostgresChip'),cc=$('advisorCutoverChip'),dc=$('advisorDomainPgChip'),tc=$('advisorDurableTelemetryChip');if(pc){pc.textContent=`PG ${pg?.migrationStatus||'N/D'} · ${pg?.mode||'FILE_JSON'}`;pc.className=pg?.schemaReady?'intel-chip good':pg?.configured?'intel-chip warn':'intel-chip neutral'}if(cc){cc.textContent=gate?.platformEligible?'Platform cutover READY':'Platform cutover BLOCKED';cc.className=gate?.platformEligible?'intel-chip good':'intel-chip warn'}if(dc){const primary=domains?.primaryDomains||status?.domains?.primaryDomains||[];dc.textContent=`Domains PG ${primary.length}/6`;dc.className=primary.length===6?'intel-chip good':primary.length?'intel-chip warn':'intel-chip neutral'}if(tc){const d=durable||status?.durableTelemetry;tc.textContent=d?.enabled?`Durable ${d.connected?'OK':d.configured?'pending':'blocked'}`:'Durable OFF';tc.className=d?.enabled?(d.connected?'intel-chip good':'intel-chip warn'):'intel-chip neutral'}const rows=reconcile?.rows||[];$('advisorPostgresReconcile').innerHTML=rows.length?rows.map(r=>`<div class="advisor-directory-row"><b>${escapeHtml(r.storeId)}<small>${escapeHtml(r.strategy||'')}</small></b><span>${escapeHtml(r.state||'')}</span><span>${r.fileCount??''}${r.postgresCount!=null?' / '+r.postgresCount:''}</span><span>${escapeHtml((r.message||r.fileSha256||'').slice(0,18))}</span></div>`).join(''):'<div class="alloc-empty">Sin reconciliación PostgreSQL.</div>';const primary=(domains?.primaryDomains||status?.domains?.primaryDomains||[]).join(', ')||'ninguno';$('advisorPostgresStatus').textContent=`Driver pg=${pg?.driverAvailable===false?'faltante':pg?.driverAvailable===true?'OK':'N/D'} · connected=${pg?.connected?'sí':'no'} · schema=${pg?.schemaReady?'ready':'N/D'} · mismatches ${reconcile?.mismatchCount??'N/D'} · domains primary: ${primary} · durable pending ${durable?.pending??status?.durableTelemetry?.pending??0}. Platform authority=${gate?.platformEligible?'POSTGRESQL':'MIXED/FILE'}.`}
async function advisorPostgresOpsLoad(features){features=features||await g2RuntimeFeatures();if(!features?.postgresPersistence)return null;const status=advisorSecurityHas('OPS_PERSISTENCE_READ')?await advisorJson('/api/g2/ops/postgres/status').catch(()=>null):null,reconcile=advisorSecurityHas('OPS_PERSISTENCE_READ')&&status?.schemaReady?await advisorJson('/api/g2/ops/postgres/reconcile').catch(()=>null):null,gate=advisorSecurityHas('OPS_PERSISTENCE_READ')&&status?.schemaReady?await advisorJson('/api/g2/ops/postgres/cutover-gate').catch(()=>null):null,domains=features?.domainPostgresMigration&&advisorSecurityHas('OPS_PERSISTENCE_READ')?await advisorJson('/api/g2/ops/postgres/domains').catch(()=>status?.domains||null):(status?.domains||null),telemetry=features?.operationalTelemetry&&advisorSecurityHas('OPS_TELEMETRY_READ')?await advisorJson('/api/g2/ops/telemetry?limit=20').catch(()=>null):null,durable=features?.durableTelemetry&&advisorSecurityHas('OPS_TELEMETRY_READ')?await advisorJson('/api/g2/ops/telemetry/durable/status').catch(()=>status?.durableTelemetry||null):(status?.durableTelemetry||null);advisorPostgresRender(status,reconcile,gate,telemetry,domains,durable);if(features?.postgresLiveValidation)await advisorPgNativeBackupsLoad().catch(()=>{});if(features?.postgresOperationsSignoff)await advisorDbOpsLoad().catch(()=>{});return{status,reconcile,gate,domains,telemetry,durable}}

