async function advisorDbOpsLoad(){const x=await advisorJson('/api/g2/ops/postgres/operations/signoff'),a=$('advisorDbOpsChip'),b=$('advisorDbSignoffChip');if(a){a.textContent=`DB Ops ${x.status}`;a.className=x.status==='READY'?'intel-chip good':'intel-chip bad'}if(b){b.textContent=x.latestApproval?(x.approvalCurrent?'Sign-off APPROVED':'Sign-off STALE'):'Sign-off pending';b.className=x.approvalCurrent?'intel-chip good':x.latestApproval?'intel-chip warn':'intel-chip neutral'}const failed=(x.checks||[]).filter(c=>c.status!=='PASS').map(c=>c.code);$('advisorDbOpsStatus').textContent=`Evidence gate ${x.status} · eligible=${x.eligible?'sí':'no'} · approval=${x.approvalCurrent?'current':x.latestApproval?'stale':'none'} · blockers: ${failed.join(', ')||'ninguno'}.`;return x}
async function advisorDbOpsRun(){if(!await window.radarConfirm('Ejecutar suite 8O? Incluye pool saturation y soak controlado contra PostgreSQL. Usar sólo en staging o ventana aprobada.'))return;const body={includeSoak:true,soakSeconds:Number($('advisorDbSoakSeconds')?.value||300),soakWorkers:Number($('advisorDbSoakWorkers')?.value||4),soakWriteRatioPct:Number($('advisorDbSoakWritePct')?.value||20)};$('advisorDbOpsStatus').textContent='Ejecutando SLO/pool/health/capacity/soak…';const x=await advisorJson('/api/g2/ops/postgres/operations/run-suite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('advisorDbOpsStatus').textContent=`Suite completa · latency ${x.latency?.passed?'PASS':'FAIL'} · pool ${x.pool?.passed?'PASS':'FAIL'} · health ${x.health?.status||'N/D'} · capacity ${x.capacity?.status||'N/D'} · soak ${x.soak?.passed?'PASS':'FAIL'} (${Math.round(x.soak?.opsPerSecond||0)} ops/s).`;await advisorDbOpsLoad();return x}
async function advisorPitrEvidenceRecord(){const body={isolatedEnvironment:true,restoreStartedAt:$('advisorPitrRestoreStarted')?.value?.trim(),serviceReadyAt:$('advisorPitrServiceReady')?.value?.trim(),lastKnownCommitAt:$('advisorPitrLastCommit')?.value?.trim(),restoredThroughAt:$('advisorPitrRestoredThrough')?.value?.trim(),dataIntegrityChecksPassed:true,evidenceRef:$('advisorPitrEvidenceRef')?.value?.trim()};if(!body.restoreStartedAt||!body.serviceReadyAt||!body.lastKnownCommitAt||!body.restoredThroughAt||!body.evidenceRef){$('advisorDbOpsStatus').textContent='Completá todos los campos PITR y una referencia de evidencia.';return}if(!await window.radarConfirm('Registrar este PITR drill como evidencia operativa verificada? Confirmás que el restore fue aislado y los checks de integridad pasaron.'))return;const x=await advisorJson('/api/g2/ops/postgres/dr/pitr-evidence',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('advisorDbOpsStatus').textContent=`PITR evidence ${x.passed?'PASS':'FAIL'} · RTO ${x.rtoSeconds}s · RPO ${x.rpoSeconds}s · ${escapeHtml(x.evidenceRef||'')}.`;await advisorDbOpsLoad();return x}
async function advisorDbSignoffApprove(){const current=await advisorDbOpsLoad();if(!current?.eligible){$('advisorDbOpsStatus').textContent='No se puede aprobar: el evidence gate no está READY.';return}const note=await window.radarPrompt('Nota de sign-off operacional (opcional):','DB operations / capacity / DR sign-off');if(note===null)return;if(!await window.radarConfirm('Aprobar sign-off 8O con tu identidad autenticada? Quedará inmutable y quedará STALE si cambia evidencia o política.'))return;const x=await advisorJson('/api/g2/ops/postgres/operations/signoff/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note,confirmSignoff:true})});$('advisorDbOpsStatus').textContent=`Sign-off APPROVED por ${escapeHtml(x.actorId||'')} · ${String(x.sha256||'').slice(0,12)}…`;await advisorDbOpsLoad();return x}
