async function advisorIdentityDirectoryLoad(features){features=features||await g2RuntimeFeatures();if(!features?.identityDirectory){const panel=$('advisorIdentityDirectoryPanel');if(panel)panel.style.display='none';return null}try{const jobs=[advisorJson('/api/g2/security/directory'),advisorJson('/api/g2/security/identity-provider')],oidc=features?.oidcFederation?advisorJson('/api/g2/auth/session').catch(()=>({active:false})):Promise.resolve({active:false});const [directory,provider,session]=await Promise.all([...jobs,oidc]);advisorDirectoryRender(directory,provider);advisorOidcRender(provider,session,features);if(features?.federationOperations)await advisorFederationOpsLoad(features,session).catch(()=>{});if(features?.productionOperations)await advisorProductionOpsLoad(features).catch(()=>{});return directory}catch(e){const panel=$('advisorIdentityDirectoryPanel');if(panel)panel.style.display='block';$('advisorDirectoryList').innerHTML=`<div class="alloc-empty">${escapeHtml(String(e.message||e))}</div>`;throw e}}
