async function advisorGenerateRecommendations(){const features=await g2RuntimeFeatures(),clientId=$('advisorClientSelect').value;if(!features?.advisorRecommendations){$('advisorRecommendationList').innerHTML='<div class="alloc-empty">Abrí Radar con INICIAR_RADAR_G2_PHASE8C.bat para habilitar Suitability/Recommendation.</div>';return}if(!clientId){$('advisorRecommendationList').innerHTML='<div class="alloc-empty">Elegí un cliente.</div>';return}$('advisorRecommendationList').innerHTML='<div class="alloc-empty">Evaluando Personalized Opportunity → Suitability → Recommendation…</div>';try{const x=await advisorJson('/api/g2/advisor/recommendations/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clientId,limit:20,includeNoAction:true})}),rows=x.recommendations||[];$('advisorRecommendationList').innerHTML=rows.length?rows.slice(0,15).map(r=>`<div class="advisor-rec-row ${String(r.action||'').toLowerCase()}"><input class="advisor-rec-select" type="checkbox" data-rec-id="${escapeHtml(String(r.recommendationId||''))}"><span class="action">${escapeHtml(r.action||'')}</span><b>${escapeHtml(r.symbol||String(r.instrumentId||''))}<small class="advisor-row-sub">${escapeHtml(r.suitability?.status||'')}</small></b><span>${escapeHtml(r.status||'PENDING')}</span><span>${escapeHtml((r.rationale||[])[0]||'')}<small class="advisor-row-sub advisor-row-sub-spaced">${escapeHtml((r.risks||[])[0]||'')}</small></span><button class="secondary-action advisor-rec-review" data-rec-id="${escapeHtml(String(r.recommendationId||''))}">Revisar 8D</button></div>`).join(''):'<div class="alloc-empty">No se generaron recomendaciones con la evidencia actual.</div>';document.querySelectorAll('.advisor-rec-review').forEach(b=>b.addEventListener('click',()=>advisorReviewRecommendation(b.dataset.recId||'')));$('advisorRecommendationNote').textContent=`${rows.length} recomendaciones · ${x.policyVersion||''} · ${x.executionMode||''}. Sin órdenes ni suggested allocation. ${(x.warnings||[]).join(' ')}`;$('advisorEngineStatus').textContent='G2 8C · Suitability + Recommendation';$('advisorEngineStatus').className='intel-chip good';return x}catch(e){$('advisorRecommendationList').innerHTML=`<div class="alloc-empty">${escapeHtml(String(e.message||e))}</div>`;throw e}}

async function advisorReviewRecommendation(recommendationId){advisorG2State.workflowRecommendationId=recommendationId;const features=await g2RuntimeFeatures(),box=$('advisorReviewPanel');if(!features?.advisorReview){box.innerHTML='<div class="alloc-empty">Abrí Radar con INICIAR_RADAR_G2_PHASE8D.bat para habilitar sizing/risk/audit review.</div>';return}if(!recommendationId)return;box.innerHTML='<div class="alloc-empty">Calculando sizing envelope + RiskBefore/RiskAfter + compliance…</div>';try{const x=await advisorJson('/api/g2/advisor/recommendations/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({recommendationId,fresh:false})}),r=x.review||{},s=r.sizing,rb=r.riskScenario?.riskBefore,ra=r.riskScenario?.riskAfter,c=r.compliance||{},fmt=v=>v==null?'N/D':Number(v).toFixed(1)+'%';box.innerHTML=`<div class="advisor-review-card ${String(c.status||'').toLowerCase()}"><b>${escapeHtml(r.action||'')} · ${escapeHtml(r.symbol||'')} · Review ${escapeHtml(c.status||'')}</b><div class="advisor-review-grid"><div><small>Sizing target</small><b>${s?`${fmt(s.targetMinWeightPct)} → ${fmt(s.targetMaxWeightPct)}`:'N/D'}</b></div><div><small>Scenario midpoint</small><b>${s?fmt(s.scenarioTargetWeightPct):'N/D'}</b></div><div><small>Volatilidad</small><b>${fmt(rb?.volatilityPct)} → ${fmt(ra?.volatilityPct)}</b></div><div><small>Max drawdown</small><b>${fmt(rb?.maxDrawdownPct)} → ${fmt(ra?.maxDrawdownPct)}</b></div></div><div class="advisor-note">Hard failed: ${escapeHtml((c.hardFailed||[]).join(', ')||'ninguno')} · Review flags: ${escapeHtml((c.reviewFlags||[]).join(', ')||'ninguno')} · Audit ${escapeHtml(String(r.auditHash||'').slice(0,16))}…</div><div class="advisor-note">Sizing = policy envelope, no asignación óptima. Risk scenario no persiste transacciones. Compliance PASS no autoriza ejecución.</div></div>`;$('advisorEngineStatus').textContent='G2 8D · Review + Sizing + Audit';$('advisorEngineStatus').className=c.status==='PASS'?'intel-chip good':c.status==='BLOCKED'?'intel-chip bad':'intel-chip warn';advisorWorkflowRefresh(recommendationId).catch(()=>{});return x}catch(e){box.innerHTML=`<div class="alloc-empty">${escapeHtml(String(e.message||e))}</div>`;throw e}}
function advisorWorkflowActor(){const p=advisorG2State.security?.principal;if(p){const role=(p.roles||[]).find(x=>['ADMIN','COMPLIANCE','ADVISOR','ASSISTANT'].includes(x))||'ASSISTANT';return{actorId:p.userId,role,displayName:p.displayName}}const id=$('advisorWorkflowActorId')?.value.trim()||$('advisorAdvisorId')?.value.trim()||'advisor:default';return{actorId:id,role:$('advisorWorkflowRole')?.value||'ADVISOR',displayName:$('advisorAdvisorName')?.value.trim()||undefined}}
